unit ShadowDemo;

interface

type
  TAncestor = class
    procedure Greet; virtual;
  end;

  TDescendant = class(TAncestor)
    procedure Greet;  // missing `override` AND missing `reintroduce`
  end;

implementation

uses SysUtils;

procedure TAncestor.Greet;
begin
  Writeln('ancestor');
end;

procedure TDescendant.Greet;
begin
  Writeln('descendant');
end;

var
  Obj : TAncestor;
begin
  Obj := TDescendant.Create;
  Obj.Greet;       // prints 'ancestor', not 'descendant'.
end.
